namespace ghidra.util.datastruct;
using static org.junit.Assert;

using org.junit;

using generic.test;

public class IntIndexManagerTest : AbstractGenericTest {

    /**
	 * Constructor
	 * @param arg0
	 */
	public IntIndexManagerTest() : base()
    {
	}
	
    /**
     * regression test driver
     */
[Test]
    public  void testIntIndexManager() {
        IntIndexManager imgr = new IntIndexManager();

        Console.WriteLine("test basic allocation");

        for(int i=0;i<10;i++) {
        	assertEquals(i, imgr.allocate());
        }


        Console.WriteLine("test deallocation");
        for(int i=5;i<8;i++) {
            imgr.deallocate(i);
        }
        for(int i = 7;i>=5;i--) {
        	assertEquals(i, imgr.allocate());
        }
        assertEquals(10, imgr.allocate());


        Console.WriteLine("test clear all");
        imgr.clear();
        for(int i=0;i<10;i++) {
        	assertEquals(i, imgr.allocate());
        }

   }//end doTest()

}


